import pyomo.environ as pyo

DATA = {
    "products": ["regular", "premium"],
    "profit_regular": 5000,
    "profit_premium": 8500,
    "demand_max_regular": 8,
    "demand_max_premium": 6,
    "total_max": 12,
}


def build_model(data=None):
    d = data or DATA
    m = pyo.ConcreteModel()

    m.P = pyo.Set(initialize=d["products"], ordered=True)

    prodlist = d["products"]
    profit_coeff = {prodlist[0]: d["profit_regular"],
                    prodlist[1]: d["profit_premium"]}
    cap_coeff    = {prodlist[0]: d["demand_max_regular"],
                    prodlist[1]: d["demand_max_premium"]}

    m.x = pyo.Var(
        m.P,
        within=pyo.NonNegativeIntegers,
        bounds=lambda m, i: (0, cap_coeff[i]),
    )

    def _obj_rule(m):
        return sum(profit_coeff[i] * m.x[i] for i in m.P)

    m.obj = pyo.Objective(rule=_obj_rule, sense=pyo.maximize)

    def _total_cap_rule(m):
        return sum(m.x[i] for i in m.P) <= d["total_max"]

    m.total_sales_cap = pyo.Constraint(rule=_total_cap_rule)

    return m

import pyomo.environ as pyo

DATA = {
    "profit": {"regular": 5000, "premium": 8500},
    "demand": {"regular": 8, "premium": 6},
    "max_total": 12,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=["regular", "premium"])

    def x_bounds(m, p):
        return (0, d["demand"][p])

    model.x = pyo.Var(
        model.P,
        within=pyo.NonNegativeIntegers,
        bounds=x_bounds,
    )

    # Objective: maximize total daily profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Total production capacity (max 12 cars of either type per day)
    def total_capacity_rule(m):
        return sum(m.x[p] for p in m.P) <= d["max_total"]

    model.total_capacity = pyo.Constraint(rule=total_capacity_rule)

    return model


